import{o as t,c as e,a as n}from"./app.f965f9eb.js";const a='{"title":"fetch请求 笔记","description":"","frontmatter":{},"headers":[{"level":2,"title":"fetch请求 笔记","slug":"fetch请求-笔记"}],"relativePath":"components/wz4.md","lastUpdated":1690504743803}',i={},o=n('<div class="tip custom-block"><p class="custom-block-title">文献</p><p>笔记 果汁 🍹</p></div><h2 id="fetch请求-笔记"><a class="header-anchor" href="#fetch请求-笔记" aria-hidden="true">#</a> fetch请求 笔记</h2><div class="warning custom-block"><p class="custom-block-title">注意事项</p><ul><li><p>注意：最外层div的id加fuckhtml和el:对应</p></li><li><p>注意：fetch是获取请求</p></li><li><p>注意：getData和myFunction异步 这里是3和4</p></li></ul><p>细节gpt解读： 在编程中，异步（Asynchronous）是一种处理任务的方式，指的是不等待当前任务完成就继续执行下一个任务。相对于同步（Synchronous）执行，异步执行可以提高程序的并发性和响应性。</p><p>在传统的同步编程模型中，程序按照顺序依次执行每个任务，并且必须等待前一个任务完成后才能执行下一个任务。这样的执行方式可能会导致阻塞，特别是在执行耗时的操作（如网络请求、文件读写等）时，会导致整个程序停滞，无法进行其他任务。</p><p>而异步编程模型通过利用回调函数、事件驱动或者协程等机制，允许程序在执行任务的同时继续执行其他任务，不必等待当前任务完成。当异步任务完成或者有新的事件触发时，系统会通知相关的回调函数或事件处理器进行相应的处理。</p><p>异步编程常见的应用场景包括：</p><ul><li><p>1.网络通信：异步编程可以用于处理网络请求和响应，如客户端发送请求后可以立即进行其他操作，而无需等待服务器的响应。</p></li><li><p>2.文件IO：在读取或写入大量数据时，异步IO操作可以提高效率，因为程序可以继续执行其他任务，而不必等待IO操作完成。</p></li><li><p>3.并发处理：异步编程可以在同时处理多个任务时提高效率，通过并发执行任务，减少等待时间。</p></li><li><p>4.用户界面：在图形界面或Web应用程序中，异步编程可以保持用户界面的响应性，避免界面卡顿。</p></li></ul><p>需要注意的是，在异步编程中，由于任务的执行是非阻塞的，所以无法直接获取任务的结果。通常会使用回调函数、Promise、Future等方式来处理异步任务的结果</p></div><p>:::</p><div class="language-"><pre><code>\ndiv id=&quot;fuckhtml&quot;\n\n    var app = new Vue({\n        el: &#39;#fuckhtml&#39;,\n        data: {\n            message: &#39;Hello Vue!&#39;\n        },\n        created() {\n            this.getData();\n        },\n        mounted(){\n               this.myFunction();\n        },\n        methods:{\n            // 获取 列表数据\n            getData() {\n                var g_id = this.getParameterByName(&#39;g_id&#39;);\n                var uid = this.getParameterByName(&#39;uid&#39;);\n                const formData = new FormData();\n                formData.append(&#39;g_id&#39;, g_id);\n                formData.append(&#39;uid&#39;, uid);\n                fetch(&#39;http://ht.9gdl.com/api/fxymlist&#39;, {\n                    method: &#39;POST&#39;,\n                    body: formData\n                })\n                    .then(response =&gt; response.json())\n                    .then(data =&gt;{\n                        console.log(data)\n                        this.message=data.data;\n                    })\n                    .catch(error =&gt; console.error(error))\n            },\n\n\n\n    })\n</code></pre></div>',5);i.render=function(n,a,i,p,l,r){return t(),e("div",null,[o])};export default i;export{a as __pageData};
